mapper.select:
SELECT c.id, c.place_id AS placeId, c.user_id AS userId, c.parent_comment_id AS parentCommentId, c.content, c.image_key AS imageKey, u.nickname, c.created_at AS createdAt, c.updated_at AS updatedAt FROM comments c JOIN users u ON c.user_id = u.id WHERE c.parent_comment_id IN
#{parentId}
ORDER BY c.created_at DESC, c.id DESC

SELECT COUNT(*)
FROM comments
WHERE place_id = #{placeId}

mapper.update:
UPDATE comments
SET content = #{content},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{commentId}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM comments

WHERE id = #{commentId}
AND user_id = #{userId}
